function Ceq = Cseries(Cvec)
usage = {
"Cseries([1 2 3, ...])"
};
if nargin == 0
    disp("Usage:\n")
    disp(usage)
    error("Cseries: no input");
end

if !isvector(Cvec)
    error("Cseries: input must be a vector");
end

Ceq=0;
for i=1:length(Cvec)
    Ceq = Ceq + 1 / Cvec(i);
end
Ceq = 1/ Ceq;
end

