function tikz(circuit,res)
  % requires latex to be installed in system
  % texlive in opensuse takes 1.4GB!!!
  % use tinytex to install only what needed (51MB):
  % - standalone
  % - pgf
  % - circuitikz
  % - pdfcrop

  Usage={
    "tikz(\"\\draw (0,0) to[R] (2,0);\",res) // string",
    "tikz({\"line1\", \"line2\", ...},res)   // cell array"
    "adjust `res` if strange rendering or kernel crash"
  };

  if nargin == 0
    disp("Usage:\n")
    disp(Usage)
    error("tikz: no input");
  end
  if nargin==1
      res=100;
  end

  % Accept string OR cell array
  if iscell(circuit)
    body = strjoin(circuit, "\n");
  else
    body = circuit;
  end

  tex = [
    "\\documentclass[tikz,border=3pt]{standalone}\n" ...
    "\\usepackage{circuitikz}\n" ...
    "\\begin{document}\n" ...
    "\\begin{circuitikz}\n" ...
    body "\n" ...
    "\\end{circuitikz}\n" ...
    "\\end{document}\n"
  ];

  tmp = tempname();
  texfile = [tmp ".tex"];
  pdffile = [tmp ".pdf"];
  auxfile = [tmp ".aux"];
  logfile = [tmp ".log"];
  cropdfile = [tmp "_crop.pdf"];
  pngbase = [tmp];
  pngfile = [pngbase "-1.png"];
  imgfile = [pngbase "_resize.png"];

  fid = fopen(texfile, "w");
  fwrite(fid, tex);
  fclose(fid);

  % Compile circuitikz to pdf
  system(sprintf(
    "pdflatex -interaction=nonstopmode -halt-on-error -output-directory %s %s &gt; /dev/null",
    fileparts(texfile), texfile
  ));

  % Auto-crop PDF (tight bounding box around circuit)
  system(sprintf(
    "pdfcrop --hires %s %s &gt; /dev/null", 
    pdffile, cropdfile
  ));


  % Convert PDF → PNG
  system(sprintf(
    "pdftoppm -png -r 400 -mono %s %s &gt; /dev/null", 
    cropdfile, pngbase
  ));

  % resize
   system(sprintf(
       "magick %s -resize %d%%  -interpolate Nearest %s &gt; /dev/null", 
       pngfile, res,imgfile
    ));



  if exist(imgfile, "file")
     img = imread(imgfile);
     % pdftoppm -mono is producing PNG with pixels in range [0,1]
     % imshow() is expecting [0,255]
     % or double, but double takes more memory
     % img = 255 * uint8(img);
     figure('Position', [0 0 size(img, 2) size(img,1)]);
     imshow(img);
     % colormap(gray(256));
     axis image off;
  else
     error("tikz: rendering failed");
  end
  delete(texfile);
  delete(pdffile);
  delete(cropdfile);
  delete(pngfile);
  delete(imgfile);
  delete(auxfile);
  delete(logfile);
end





